import { forwardRef, type ReactNode } from 'react';

export type StatsTrend = 'up' | 'down' | 'neutral';

export type StatsCardProps = {
  value: string;
  label: string;
  trend?: StatsTrend;
  trendValue?: string;
  compact?: boolean;
  gradient?: boolean;
  className?: string;
};

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

function TrendIcon({ direction }: { direction: 'up' | 'down' }) {
  if (direction === 'up') {
    return (
      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
        <polyline points="22 7 13.5 15.5 8.5 10.5 2 17" />
        <polyline points="16 7 22 7 22 13" />
      </svg>
    );
  }
  return (
    <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
      <polyline points="22 17 13.5 8.5 8.5 13.5 2 7" />
      <polyline points="16 17 22 17 22 11" />
    </svg>
  );
}

export const StatsCard = forwardRef<HTMLDivElement, StatsCardProps>(
  ({ value, label, trend, trendValue, compact, gradient, className }, ref) => {
    return (
      <div
        ref={ref}
        className={cn(
          'stats-card',
          compact && 'stats-card--compact',
          gradient && 'stats-card--gradient',
          className,
        )}
      >
        <span className="stats-card__value">{value}</span>
        <span className="stats-card__label">{label}</span>
        {trend && trendValue && (
          <span className={cn('stats-card__trend', `stats-card__trend--${trend}`)}>
            {trend !== 'neutral' && (
              <span className="stats-card__trend-icon" aria-hidden="true">
                <TrendIcon direction={trend} />
              </span>
            )}
            {trendValue}
          </span>
        )}
      </div>
    );
  },
);

StatsCard.displayName = 'StatsCard';

/* ============================================================
   StatsCard — metric number + label + optional trend indicator
   ============================================================ */

.stats-card {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-3);
  padding: var(--spacing-8);
  border-radius: var(--radius-xl);
  background-color: var(--card);
  border: var(--stroke-hairline) solid var(--border);
  transition: border-color var(--duration-150) var(--easing-out);
}

.stats-card--compact {
  padding: var(--spacing-4);
  gap: var(--spacing-2);
  border-radius: var(--radius-lg);
}

/* ---- Value (big number) ---- */
.stats-card__value {
  font-size: var(--font-size-4xl);
  font-weight: var(--font-weight-bold);
  line-height: 1;
  letter-spacing: -0.03em;
  color: var(--foreground);
  font-variant-numeric: tabular-nums;
}

.stats-card--compact .stats-card__value {
  font-size: var(--font-size-2xl);
}

.stats-card--gradient .stats-card__value {
  /* fallback keeps standalone installs working without the utilities item */
  background: var(--gradient-brand, linear-gradient(135deg, var(--color-forest) 0%, var(--brand) 100%));
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

/* ---- Label ---- */
.stats-card__label {
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  color: var(--muted-foreground);
  line-height: 1.4;
}

/* ---- Trend indicator ---- */
.stats-card__trend {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-1);
  font-size: var(--font-size-xs);
  font-weight: var(--font-weight-medium);
  line-height: 1;
  margin-top: var(--spacing-1);
}

.stats-card__trend--up {
  color: var(--success);
}

.stats-card__trend--down {
  color: var(--destructive);
}

.stats-card__trend--neutral {
  color: var(--muted-foreground);
}

.stats-card__trend-icon {
  display: flex;
  width: 1em;
  height: 1em;
}

.stats-card__trend-icon svg {
  width: 100%;
  height: 100%;
}

